const paths={random:'M4 4h16v16H4z M8 8h.01 M16 8h.01 M12 12h.01 M8 16h.01 M16 16h.01',explore:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M16 8l-3 5-5 3 3-5z',queue:'M5 3h14a2 2 0 0 1 2 2v3a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2z M5 14h14a2 2 0 0 1 2 2v3a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-3a2 2 0 0 1 2-2z',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',subscriptions:'M7 3h10 M5 6h14 M5 9h14a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-8a2 2 0 0 1 2-2z M10 12l5 3-5 3z',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z M15.5 12a3.5 3.5 0 1 1-7 0 3.5 3.5 0 0 1 7 0',refresh:'M20 3v5h-5 M20 8a8 8 0 1 0 .2 7.5',pause:'M9 8v8 M15 8v8 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',play:'M9 7l8 5-8 5z M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',plus:'M12 5v14 M5 12h14',minus:'M5 12h14',close:'M6 6l12 12 M18 6L6 18',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',chevron:'M9 5l7 7-7 7',storage:'M3 4h18v6H3z M3 14h18v6H3z M6 7h.01 M6 17h.01',film:'M4 3h16v18H4z M4 8h16 M4 16h16 M8 3v18 M16 3v18',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',more:'M12 5h.01 M12 12h.01 M12 19h.01',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',check:'M5 12l4 4L19 6',cloud:'M6 18a5 5 0 1 1 0-10 6 6 0 0 1 12 0 5 5 0 1 1 0 10z'};
const icon=(name,extra='')=>`<svg ${extra} viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.film}"/></svg>`;
const titles={queue:'Очередь',search:'Поиск',subscriptions:'Подписки',settings:'Настройки'};
const defaults={server:'',demo:false,episodeLimit:5,reserveGb:5,capGb:null,pollSeconds:10};
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
let selectedTheme=normalizeTheme(document.documentElement.dataset.theme);
applyTheme(selectedTheme);
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',updateThemeColor);
const state={settings:{...defaults,...localSettings({...defaults,...read('wn-settings',{})})},token:sessionStorage.getItem('wn-token')||'',gateway:false,tmdb:false,tab:routeForHash(location.hash).tab,packs:[],subs:[],status:null,connected:false,error:'',loading:true,queueFilter:'all',subFilter:'all',search:{query:'',kind:'series',raw:[],loading:false,error:'',quality:'',voice:'',tracker:'',season:'',sort:''},modal:null,pending:false};
if(new URLSearchParams(location.search).get('demo')==='1')state.settings.demo=true;
const $=selector=>document.querySelector(selector);const sheet=$('#sheet');let generation=0,refreshPromise=null,searchTimer,searchAbort,toastTimer,opener;
const bigBang='https://static.tvmaze.com/uploads/images/medium_portrait/173/433868.jpg';
const pulp='https://thumb.wikimedia.org/wikipedia/ru/thumb/9/93/Pulp_Fiction.jpg/330px-Pulp_Fiction.jpg?utm_source=ru.wikipedia.org&utm_campaign=api&utm_content=thumbnail';
const makeDemo=()=>({status:{diskTotalGb:67,diskUsedGb:42,diskFreeGb:25,isPaused:false,episodeCountLimit:5,reserveGb:5,totalPacksCount:3},packs:[{hash:'bigbang-demo',title:'Теория большого взрыва',kind:'series',season:12,startEpisode:22,state:'READY',progress:1,totalSize:16.5*1024**3,readyEpisodes:3,totalEpisodes:24,posterUrl:bigBang,episodes:Array.from({length:24},(_,i)=>({index:i,label:`S12E${String(i+1).padStart(2,'0')}`,name:`The.Big.Bang.Theory.S12E${i+1}.mkv`,season:12,episode:i+1,size:659.2*1024**2,status:i<21?'SKIPPED':'COMPLETED',progress:i<21?0:1,isPublished:i>=21}))},{hash:'pulp-demo',title:'Криминальное чтиво',kind:'movie',state:'COMPLETE',progress:1,totalSize:1.5*1024**3,posterUrl:pulp,episodes:[{index:0,label:'Фильм',size:1.5*1024**3,status:'COMPLETED',progress:1,isPublished:true}]},{hash:'severance-demo',title:'Разделение',kind:'series',season:2,startEpisode:1,state:'DOWNLOADING',progress:.64,downloadSpeed:8.2*1024**2,totalSize:24*1024**3,readyEpisodes:6,totalEpisodes:10,episodes:Array.from({length:10},(_,i)=>({index:i,label:`S02E${String(i+1).padStart(2,'0')}`,season:2,episode:i+1,size:2.4*1024**3,status:i<6?'COMPLETED':i===6?'DOWNLOADING':'WAITING_LIMIT',progress:i<6?1:i===6?.4:0}))}],subs:[{id:'sub-demo',showTitle:'Теория большого взрыва',status:'RELEASE_FOUND',preferredQuality:'1080p',preferredVoice:'Дубляж',nextEpisodeLabel:'S12E22',posterUrl:bigBang,candidateReleaseTitle:'Теория большого взрыва S12E22 1080p',candidateReleaseMagnet:'magnet:?xt=urn:btih:38bdf8818cf84f46e50284c7161b220d1117abcd'},{id:'sub-waiting',showTitle:'Разделение',status:'ACTIVE',preferredQuality:'1080p',preferredVoice:'LostFilm',nextEpisodeLabel:'Следующий сезон'}]});
let demo=makeDemo();
const integrationsUI=createIntegrationUI({request,toast,onChange:renderHeader});
let settingsDraft={...state.settings,token:state.token},pollTimer,searchEpoch=0;
const dirtyLimits=new Set();let limitsLoaded=false,pollDirty=false;
function syncPoll(config){if(!Number.isInteger(config?.pollSeconds))return;const changed=state.settings.pollSeconds!==config.pollSeconds;state.settings.pollSeconds=config.pollSeconds;if(!pollDirty)settingsDraft.pollSeconds=config.pollSeconds;const value=document.querySelector('[data-setting-value="pollSeconds"]');if(value&&!pollDirty)value.textContent=config.pollSeconds+' сек';if(changed)schedulePoll();}
async function loadWebSettings(){const config=await integrationsUI.load();syncPoll(config);return config;}
function syncLimits(status){synchronizeLimits(state.settings,settingsDraft,status,dirtyLimits);limitsLoaded=true;const group=$('#queue-limits');if(group)group.innerHTML=limitsContent();}

function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
function field(name,label,value='',type='text',attrs=''){return `<label class="field"><span>${e(label)}</span><input name="${e(name)}" type="${type}" value="${e(value)}" ${attrs}></label>`;}
const track=value=>`<div class="track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(clamp(value)*100)}"><span style="--progress:${clamp(value)*100}%"></span></div>`;
function safeImage(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function cover(item,title,kind='series'){const url=safeImage(item.posterUrl);return `<div class="cover" data-title="${e(title)}" data-kind="${e(mediaKind(kind))}" ${/^[a-f0-9]{40}$/i.test(item.hash||'')?`data-pack="${e(item.hash)}"`:''}>${icon('film')}${url?`<img src="${e(url)}" alt="" loading="lazy" referrerpolicy="no-referrer" data-origin="server">`:''}</div>`;}
function badge(text,color=''){return `<span class="status ${color}">${e(text)}</span>`;}
function packStatus(p){const s=String(p.state).toUpperCase();if(s==='COMPLETE')return badge('Скачан','green');if(s==='READY')return badge(p.kind==='series'&&p.readyEpisodes<p.totalEpisodes?'Есть готовые серии':'Готово','green');return badge(({DOWNLOADING:'Загружается',STOPPED:'На паузе',CHECKING:'Проверка файлов',METADATA:'Получаем данные'})[s]||s,s==='STOPPED'?'amber':'blue');}
function packCard(p){const series=String(p.kind).toLowerCase()==='series';return `<article class="media-card interactive" data-action="pack" data-id="${e(p.hash)}" tabindex="0" role="button" aria-label="Открыть ${e(p.title)}">${cover(p,p.title,p.kind)}<div class="card-content"><div class="pack-card-heading"><h3>${e(p.title)}</h3><div class="pack-card-status">${packStatus(p)}</div></div><p class="meta">${series?`<span>Сезон ${e(p.season)}</span>${p.totalEpisodes?`<span>· ${e(p.readyEpisodes)} из ${e(p.totalEpisodes)} серий</span>`:''}`:`<span>Фильм · ${bytes(p.totalSize)}</span>`}</p>${p.state==='DOWNLOADING'&&p.progress<1?`<div class="progress-wrap">${track(p.progress)}<p>${Math.round(clamp(p.progress)*100)}%${p.downloadSpeed>0?` · ${bytes(p.downloadSpeed)}/с`:''}</p></div>`:''}</div></article>`;}
function empty(title,description,buttons=''){return `<div class="empty"><div class="empty-icon">${icon('film')}</div><h2>${e(title)}</h2><p>${e(description)}</p>${buttons?`<div class="empty-actions">${buttons}</div>`:''}</div>`;}
function filters(items,selected,action){return `<div class="filters ${['queue-filter','sub-filter','kind'].includes(action)?'segmented':''}" role="group" aria-label="Фильтры">${items.map(([value,label])=>`<button class="chip" data-action="${action}" data-value="${value}" aria-pressed="${value===selected}">${label}</button>`).join('')}</div>`;}
function renderNav(){for(const id of ['desktop-nav','mobile-nav']){const nav=$(`#${id}`);if(!nav.querySelector('a'))nav.innerHTML=Object.entries(titles).map(([key,label])=>`<a href="#${key}"><span class="nav-icon">${icon(key)}</span><span>${label}</span></a>`).join('');for(const a of nav.querySelectorAll('a')){const selected=a.getAttribute('href')==='#'+state.tab;a.classList.toggle('active',selected);if(selected&&a.getAttribute('aria-current')!=='page')a.setAttribute('aria-current','page');else if(!selected&&a.hasAttribute('aria-current'))a.removeAttribute('aria-current');}}}
let headerMarkup='';
function renderHeader(){const isQueue=state.tab==='queue';const markup=`<div class="header-copy"><h1 class="mobile-brand"><img class="home-logo" src="./logo.svg" alt="">${isQueue?'WatchNext':titles[state.tab]}</h1></div><div class="header-actions">${isQueue&&integrationsUI.connected()?`<a class="secondary outline small jellyfin-home" href="${e(integrationsUI.home())}">Jellyfin ↗</a>`:''}${isQueue?`<button class="icon-btn" data-action="refresh" aria-label="Обновить очередь">${icon('refresh')}</button><button class="icon-btn" data-action="pause" aria-label="${state.status?.isPaused?'Возобновить':'Приостановить'} очередь" ${!state.connected?'disabled':''}>${icon(state.status?.isPaused?'play':'pause')}</button>`:state.tab==='subscriptions'?`<button class="secondary small" data-action="add-sub" aria-label="Добавить подписку">${icon('plus')}<span>Добавить</span></button>`:''}</div>`;if(markup!==headerMarkup){$('#header').innerHTML=markup;headerMarkup=markup;}$('#mode-banner').innerHTML=state.settings.demo?'<div class="mode-banner"><span>Демо-режим · тестовые данные</span><button data-action="connect">Подключить сервер</button></div>':'';}
function initialContent(){return empty('Подключим вашу очередь','Укажите адрес сервера WatchNext или посмотрите, как всё устроено, в демо-режиме.',`<button class="primary" data-action="connect">${icon('link')}Подключить сервер</button><button class="icon-btn full" data-action="demo">Посмотреть демо</button>`);}
function queueContent(){if(state.loading&&!state.status)return skeletonCards('Загружаем очередь…');if(!state.connected&&!state.status&&!state.error)return initialContent();const status=state.status;const filtered=state.packs.filter(p=>state.queueFilter==='all'||(state.queueFilter==='downloading'?p.state==='DOWNLOADING':isReady(p)));return `${state.error?`<div class="error-banner"><div><strong>Нет связи с сервером</strong><p>${e(state.error)}</p>${state.packs.length?'<p>Ниже — данные последней успешной синхронизации.</p>':''}</div><button class="icon-btn" data-action="connect" aria-label="Открыть настройки подключения">${icon('settings')}</button></div>`:''}${status?.diskTotalGb>0?`<section class="storage" aria-label="Место на диске">${icon('storage')}<div class="storage-body"><div class="storage-top"><span>Занято ${Number(status.diskUsedGb).toFixed(0)} из ${Number(status.diskTotalGb).toFixed(0)} ГБ</span><span class="muted">Свободно ${Number(status.diskFreeGb).toFixed(0)} ГБ</span></div>${track(status.diskUsedGb/status.diskTotalGb)}${status.diskTotalGb-status.diskUsedGb-status.diskFreeGb>=0.5?`<small class="storage-reserve">${Math.max(0,Math.round(status.diskTotalGb)-Math.round(status.diskUsedGb)-Math.round(status.diskFreeGb))} ГБ — резерв системы</small>`:''}</div></section>`:''}<div class="section-heading"><h2>Очередь</h2><span class="count">${state.packs.length}</span></div>${filters([['all','Все'],['downloading','Загружаются'],['ready','Готово']],state.queueFilter,'queue-filter')}<div class="cards">${filtered.map(packCard).join('')}</div>${!filtered.length?empty(state.queueFilter==='downloading'?'Сейчас ничего не загружается':state.packs.length?'Здесь пока пусто':state.loading?'Загружаем очередь…':'Очередь пуста',state.queueFilter==='downloading'?'Новые загрузки появятся здесь.':state.packs.length?'Выберите другой фильтр.':state.error?'Проверьте адрес сервера и повторите подключение.':'Найдите фильм или сериал либо добавьте magnet-ссылку.'):''}<button class="secondary outline full add-link" data-action="add" ${!state.connected?'disabled':''}>${icon('plus')}Добавить ссылку</button>`;}
function resultCard(r,index){return `<article class="media-card">${cover(r,r.title,r.detectedKind?.toLowerCase()||state.search.kind)}<div class="card-content"><h3 class="result-title">${e(r.title)}</h3><p class="meta"><span>${e(r.quality)}</span>${r.voices?.length?`<span>· ${e(r.voices.join(', '))}</span>`:''}</p><p class="meta"><span>${bytes(r.size)}</span><span>· ${e(r.seeders)} сидов</span></p><p class="meta" style="color:var(--accent)">${e(r.tracker)}</p><div class="card-actions"><button class="secondary small" data-action="add-result" data-id="${index}">${icon('download')}В очередь</button><button class="secondary outline small" data-action="want-result" data-id="${index}">Хочу посмотреть</button></div></div></article>`;}
let searchMode=routeForHash(location.hash).mode;
function openMovieSearch(movie){searchMode='release';state.search.kind=movie.kind==='series'?'series':'movie';state.search.query=`${movie.title}${movie.year?' '+movie.year:''}`.slice(0,120);state.tab='search';location.hash='search';render();runSearch();}
const wishlist=createWishlistUI({request:(path,options={})=>request(path,{...options,server:''}),onSearch:openMovieSearch,toast});
const discovery=createDiscovery({request:(path,options={})=>request(path,{...options,server:''}),onMessage:toast,onSearch:openMovieSearch,onWant:wishlist.add,wishlistHTML:wishlist.html});
const exploreUI=createExploreUI({request:(path,options={})=>request(path,{...options,server:''}),onSearch:openMovieSearch,onWant:wishlist.add});
function searchContent(){const modes=searchMode==='release'?'':'<button class="search-back" data-action="search-mode" data-value="release">← Поиск по названию</button>';if(searchMode==='random')return modes+discovery.html();if(searchMode==='discover')return modes+exploreUI.html()+wishlist.html();const label=state.search.kind==='series'?'Название сериала':'Название фильма';return modes+`<section class="release-search-form" aria-label="Поиск раздач">${filters([['series','Сериалы'],['movie','Фильмы']],state.search.kind,'kind')}<div class="search-box">${icon('search')}<input id="search-input" aria-label="${label}" type="search" value="${e(state.search.query)}" placeholder="${label}" autocomplete="off" enterkeyhint="search"><button class="icon-btn" data-action="clear-search" aria-label="Очистить поиск" ${state.search.query?'':'hidden'}>${icon('close')}</button></div></section><div id="search-results"></div>${wishlist.html()}`;}
function searchStart(){const examples=state.search.kind==='series'?['Разделение','Наследники','Теория большого взрыва']:['Дюна','Интерстеллар','Криминальное чтиво'];return `<section class="search-start"><h2>Попробуйте найти</h2><div class="search-examples">${examples.map(title=>`<button class="secondary outline" data-action="search-example" data-query="${e(title)}">${icon('search')}${e(title)}</button>`).join('')}</div><h2>Или найдите идею для вечера</h2><div class="search-shortcuts"><button data-action="search-mode" data-value="discover">${icon('explore')}<span><strong>Подборки и фильмографии</strong><small>Выбирайте по настроению или любимому актёру</small></span>${icon('chevron')}</button><button data-action="search-mode" data-value="random">${icon('random')}<span><strong>Случайный фильм</strong><small>Задайте жанр, годы и рейтинг</small></span>${icon('chevron')}</button></div></section>`;}
function renderResults(){const area=$('#search-results');if(!area)return;const s=state.search;if(s.loading&&!s.raw.length){area.innerHTML=skeletonCards('Ищем раздачи…');return;}if(!s.query.trim()){area.innerHTML=searchStart();return;}if(s.error){area.innerHTML=empty('Поиск недоступен',s.error,'<button class="secondary" data-action="retry-search">Повторить поиск</button>');return;}const options=(key,label,values)=>`<select data-filter="${key}" aria-label="${label}"><option value="">${label}</option>${values.map(v=>`<option value="${e(v)}" ${s[key]===v?'selected':''}>${e(v)}</option>`).join('')}</select>`;const filtered=sortReleases(s.raw,s.sort).filter(({r})=>(!s.quality||r.quality===s.quality)&&(!s.voice||r.voices?.includes(s.voice))&&(!s.tracker||r.tracker===s.tracker)&&(s.kind!=='series'||!s.season||releaseSeasons(r.title).includes(Number(s.season))));area.innerHTML=`${s.loading?'<p class="search-progress" role="status">Найденные раздачи уже доступны · остальные трекеры ещё отвечают…</p>':s.note?`<p class="search-progress">${e(s.note)}</p>`:''}${s.raw.length?`<div class="filter-selects">${s.kind==='series'?`<select data-filter="season" aria-label="Сезон"><option value="">Все сезоны</option>${[...new Set(s.raw.flatMap(r=>releaseSeasons(r.title)))].sort((a,b)=>a-b).map(n=>`<option value="${n}" ${Number(s.season)===n?'selected':''}>Сезон ${n}</option>`).join('')}</select>`:''}${options('quality','Качество',[...new Set(s.raw.map(r=>r.quality))])}${options('voice','Озвучка',[...new Set(s.raw.flatMap(r=>r.voices||[]))])}${options('tracker','Все трекеры',[...new Set(s.raw.map(r=>r.tracker))])}<select data-filter="sort" aria-label="Сортировка"><option value="">По умолчанию</option><option value="size-asc" ${s.sort==='size-asc'?'selected':''}>Размер: меньше сначала</option><option value="size-desc" ${s.sort==='size-desc'?'selected':''}>Размер: больше сначала</option></select></div><p class="search-count">Найдено релизов: ${filtered.length}</p>`:''}<div class="cards">${filtered.map(({r,i})=>resultCard(r,i)).join('')}</div>${!filtered.length?empty('Ничего не найдено',s.raw.length?'Измените выбранные фильтры.':'Попробуйте другое название или тип контента.'):''}`;hydrateCovers();}
function subCard(s){const ready=s.status==='RELEASE_FOUND';return `<article class="media-card">${cover(s,s.showTitle)}<div class="card-content"><div class="card-top"><h3>${e(s.showTitle)}</h3><button class="icon-btn" data-action="sub-menu" data-id="${e(s.id)}" aria-label="Действия с подпиской ${e(s.showTitle)}">${icon('more')}</button></div>${badge(ready?'Доступен новый релиз':s.status==='EPISODE_OUT'?'Ждём нужную озвучку':s.status==='UP_TO_DATE'?'Все релизы добавлены':'Ждём новую серию',ready?'green':s.status==='EPISODE_OUT'?'amber':'')}<p class="meta">${e(s.nextEpisodeLabel||'')}</p>${s.nextEpisodeDate?`<p class="meta">${e(s.nextEpisodeDate)}</p>`:''}<p class="meta"><span>${e(s.preferredQuality||'Любое качество')}</span><span>· ${e(s.preferredVoice||'Любая озвучка')}</span></p>${ready?`<div class="card-actions"><button class="secondary small" data-action="import" data-id="${e(s.id)}">${icon('download')}В очередь</button></div>`:''}</div></article>`;}
function subscriptionsContent(){if(state.loading&&!state.status)return skeletonCards('Загружаем подписки…');if(!state.connected&&!state.subs.length)return initialContent();const list=state.subs.filter(s=>state.subFilter==='all'||(state.subFilter==='new'?s.status==='RELEASE_FOUND':s.status!=='RELEASE_FOUND'));return `${filters([['all','Все'],['new','Новые серии'],['waiting','Ожидаются']],state.subFilter,'sub-filter')}<div class="cards">${list.map(subCard).join('')}</div>${!list.length?empty('Ваши сериалы — в одном месте',state.subs.length?'Пока нет сериалов в этой категории.':'Добавьте сериал, выберите качество и озвучку — сервер будет отслеживать новые релизы.',!state.subs.length?'<button class="primary" data-action="add-sub">Добавить сериал</button>':''):''}`;}
const numericFields={episodeLimit:{title:'Серий вперёд',help:'Сколько серий загружать заранее',unit:'серий',min:1,max:1000,integer:true,presets:[3,5,10,15,20]},reserveGb:{title:'Свободное место',help:'Оставлять на диске не меньше этого объёма',unit:'ГБ',min:0,max:100,presets:[2,5,10,20,50]},capGb:{title:'Максимальный объём',help:'0 — без ограничений',unit:'ГБ',min:0,max:500,presets:[0,25,50,100,200]},pollSeconds:{title:'Интервал проверки очереди',help:'Как часто обновлять состояние очереди',unit:'сек',min:1,max:30,integer:true,presets:[3,5,10,15,30]}};
const numberRow=key=>{const f=numericFields[key];return `<button type="button" class="setting-row" data-action="number" data-key="${key}" ${!limitsLoaded&&!state.settings.demo&&key!=='pollSeconds'?'disabled':''}><div class="setting-copy"><strong>${f.title}</strong></div><span class="setting-value" data-setting-value="${key}">${settingsDraft[key]==null?(key==='capGb'?'0\u00a0ГБ':'Без ограничений'):`${settingsDraft[key]}\u00a0${f.unit}`}</span>${icon('chevron')}</button>`;};
function limitsContent(){return `${numberRow('episodeLimit')}${numberRow('reserveGb')}${numberRow('capGb')}`;}
function settingsContent(){return `<form id="settings-form" class="settings-layout">
<details class="settings-group settings-disclosure"><summary><span><strong>Лимиты очереди</strong></span>${icon('chevron')}</summary><div class="settings-body settings-rows" id="queue-limits">${limitsContent()}</div></details>
<details class="settings-group settings-disclosure"><summary><span><strong>Обновление</strong></span>${icon('chevron')}</summary><div class="settings-body settings-rows">${numberRow('pollSeconds')}</div></details>
<details class="settings-group settings-disclosure" ${!state.gateway||settingsDraft.server?'open':''}><summary><span><strong>Подключение</strong></span>${icon('chevron')}</summary><div class="settings-body">${field('server','Адрес сервера',settingsDraft.server,'url','placeholder="https://watchnext.example" autocomplete="url" autocapitalize="none" spellcheck="false"')}<p class="field-hint">${state.gateway?'Оставьте пустым, чтобы использовать текущий сервер.':'Укажите адрес API вашего сервера WatchNext.'}</p><label class="field"><span>API токен</span><div class="password-field"><input name="token" type="password" value="${e(settingsDraft.token)}" placeholder="Необязательно" autocomplete="off" autocapitalize="none" spellcheck="false"><button type="button" class="icon-btn" data-action="toggle-token" aria-label="Показать токен">${icon('eye')}</button></div></label><p class="field-hint">Хранится только в этой вкладке браузера.</p><button type="button" class="secondary outline full" data-action="test">${icon('cloud')}Проверить связь</button><div id="connection-result" class="server-state" role="status"></div></div></details>
<details class="settings-group settings-disclosure appearance-group"><summary><span><strong>Оформление</strong></span>${icon('chevron')}</summary><div class="settings-body"><p class="section-note">Применяется сразу и сохраняется на этом устройстве.</p>${themeChoices(selectedTheme)}</div></details>
<details class="settings-group settings-disclosure"><summary><span><strong>Демонстрация</strong></span>${icon('chevron')}</summary><div class="settings-body"><div class="setting-row"><div class="setting-copy"><strong>Демо-режим</strong><p>Показывать примеры вместо вашей очереди</p></div><label class="toggle"><input type="checkbox" name="demo" aria-label="Демо-режим" ${settingsDraft.demo?'checked':''}><span></span></label></div></div></details>
<div class="settings-save"><div class="form-error" id="settings-error" role="alert"></div><button class="primary" type="submit">${icon('check')}Сохранить настройки</button></div></form>${state.gateway?'<div class="settings-section-title"><h2>Сервисы</h2></div><div id="integration-settings"></div>':''}<div class="settings-footnote">${/iPhone/.test(navigator.userAgent)&&!isStandalone()?'<button class="secondary outline full" data-action="install">Добавить на экран Домой</button>':''}</div>`;}

function render(){const savedCovers=new Map([...document.querySelectorAll('.cover')].map(el=>[JSON.stringify([el.dataset.pack,el.dataset.title,el.dataset.kind]),el]));renderNav();renderHeader();$('#content').innerHTML=({queue:queueContent,search:searchContent,subscriptions:subscriptionsContent,settings:settingsContent})[state.tab]();document.querySelectorAll('.cover').forEach(el=>{const old=savedCovers.get(JSON.stringify([el.dataset.pack,el.dataset.title,el.dataset.kind]));if(old?.querySelector('img')?.complete&&old.querySelector('img').naturalWidth)el.replaceWith(old);});if(state.tab==='settings'&&state.gateway)integrationsUI.mount();if(state.tab==='search'){renderResults();if(searchMode==='discover')exploreUI.mount();if(searchMode==='random')discovery.mount();wishlist.mount();}hydrateCovers();}
async function request(path,{method='GET',body,signal,server=state.settings.server,token=state.token}={}){const issue=connectionProblem(server,location.protocol);if(issue)throw new Error(issue);const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),(path.startsWith('/api/discover/')||path.startsWith('/api/explore/'))?65000:path.startsWith('/api/search')?45000:18000);const onAbort=()=>controller.abort();signal?.addEventListener('abort',onAbort,{once:true});try{const res=await fetch(apiURL(server,path),{method,headers:{Accept:'application/json',...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:`Bearer ${token}`}:{})},body:body?JSON.stringify(body):undefined,signal:controller.signal,credentials:'omit',cache:'no-store'});if(!res.ok){let payload;try{payload=await res.json();}catch{}const error=new Error(apiError(res.status,payload));error.status=res.status;throw error;}const text=await res.text();if(!text)return {};try{return JSON.parse(text);}catch{throw new Error('По этому адресу сервер не вернул JSON API WatchNext');}}catch(err){if(err.name==='AbortError')throw new Error('Сервер не ответил вовремя. Повторите запрос.');if(err instanceof TypeError)throw new Error('Не удалось подключиться. Проверьте адрес, доступ к сети и CORS на сервере.');throw err;}finally{clearTimeout(timeout);signal?.removeEventListener('abort',onAbort);}}
async function refresh(manual=false){if(refreshPromise)return refreshPromise;if(state.settings.demo){state.loading=false;state.packs=demo.packs;state.subs=demo.subs;state.status=demo.status;state.connected=true;state.error='';render();return;}if(!state.settings.server&&!state.gateway){state.loading=false;state.connected=false;render();return;}const gen=generation;state.loading=true;if(!state.status&&state.tab==='queue')render();else renderHeader();refreshPromise=(async()=>{try{const status=await request('/api/status');const [packs,subs]=await Promise.all([request('/api/packs'),request('/api/subscriptions')]);if(gen!==generation)return;if(!Array.isArray(packs)||!Array.isArray(subs))throw new Error('Сервер вернул неподдерживаемый формат списка');state.status=status;syncLimits(status);state.packs=packs.map(p=>({...p,kind:mediaKind(p.kind)}));state.subs=subs;state.connected=true;state.error='';if(!['settings','search','random'].includes(state.tab))render();else renderHeader();if(state.modal?.type==='pack'&&!sheet.querySelector('form'))updateOpenPack();if(manual)toast('Очередь обновлена');}catch(err){if(gen!==generation)return;state.error=err.message;state.connected=false;if(state.tab==='queue')render();else if(manual)toast(err.message);}finally{if(gen===generation){state.loading=false;refreshPromise=null;if(state.tab==='queue')render();else renderHeader();}}})();return refreshPromise;}
async function runSearch(){const requestId=++searchEpoch;const s=state.search;searchAbort?.abort();if(!s.query.trim()){s.raw=[];s.loading=false;s.error='';renderResults();return;}if(!state.connected&&!state.settings.demo){s.error='Сначала подключите сервер в настройках.';s.raw=[];renderResults();return;}const query=s.query,kind=s.kind;s.raw=[];s.quality=s.voice=s.tracker=s.season='';s.loading=true;s.error='';s.note='';renderResults();searchAbort=new AbortController();try{let results;if(state.settings.demo){await new Promise(r=>setTimeout(r,260));results=[{title:`${query} (1994) BDRip 1080p | Дубляж`,tracker:'Демо · RuTracker',size:1.5*1024**3,seeders:128,quality:'1080p',voices:['Дубляж'],magnet:'magnet:?xt=urn:btih:38bdf8818cf84f46e50284c7161b220d1117abcd',detectedKind:kind,detectedSeason:1,detectedStartEpisode:1},{title:`${query} WEB-DL 2160p | Оригинал`,tracker:'Демо · RuTor',size:18*1024**3,seeders:42,quality:'2160p',voices:['Оригинал'],magnet:'magnet:?xt=urn:btih:38bdf8818cf84f46e50284c7161b220d1117abcd',detectedKind:kind}];}else {await progressiveSearch({request,query,kind,signal:searchAbort.signal,onUpdate:page=>{if(query!==s.query||kind!==s.kind||requestId!==searchEpoch)return;if(Array.isArray(page.results))s.raw=page.results;s.loading=!page.done;s.note=page.warnings?.length?'Не ответили: '+page.warnings.join(', '):'';if(page.error&&!s.raw.length)s.error=page.error;renderResults();}});return;}if(query!==s.query||kind!==s.kind||requestId!==searchEpoch)return;s.raw=Array.isArray(results)?results:[];s.quality=s.voice=s.tracker=s.season='';}catch(err){if(query===s.query&&kind===s.kind&&requestId===searchEpoch){if(s.raw.length)s.note=err.message;else s.error=err.message;}}finally{if(query===s.query&&kind===s.kind&&requestId===searchEpoch){s.loading=false;renderResults();}}}
function openSheet(type,id,html){opener=document.activeElement;state.modal={type,id};sheet.innerHTML=html;document.body.classList.add('modal-open');if(!sheet.open)sheet.showModal();hydrateCovers();}
function closeSheet(){sheet.close();state.modal=null;document.body.classList.remove('modal-open');opener?.isConnected&&opener.focus();}
const shell=(title,body)=>`<div class="sheet-head"><h2 id="sheet-title">${e(title)}</h2><button class="icon-btn" data-action="close" aria-label="Закрыть">${icon('close')}</button></div><div class="sheet-body">${body}</div>`;
function packDetails(p){return shell(p.title,`<p class="sheet-meta"><span>${p.kind==='movie'?'Фильм':'Сериал'}</span>${p.kind!=='movie'?`<span>Сезон ${e(p.season)} · с ${e(p.startEpisode)} серии</span>`:''}</p><p class="sheet-meta"><span>${bytes(p.totalSize)}</span></p><div class="detail-status">${packStatus(p)}<button class="icon-btn" data-action="detail-refresh" aria-label="Обновить детали">${icon('refresh')}</button></div><div class="pack-primary">${integrationsUI.connected()?`<button class="primary" data-action="jellyfin" data-id="${e(p.hash)}">${icon('play')}Смотреть в Jellyfin</button>`:''}<button class="secondary outline pack-more" data-action="pack-menu" data-id="${e(p.hash)}">Ещё ${icon('more')}</button></div>${p.kind!=='movie'?`<div class="pack-secondary"><button class="secondary outline" data-action="change-start" data-id="${e(p.hash)}">${icon('download')}С какой серии скачивать</button></div>`:''}<h3 class="episodes-heading"><span>${p.kind==='movie'?'Файлы':'Эпизоды'}</span><span class="muted">${p.episodes?.length||0}</span></h3>${(p.episodes||[]).map(ep=>{const {label,color,fileRemoved,canDelete}=episodeView(ep);return `<div class="episode"><div class="episode-main"><div class="episode-copy"><strong>${e(ep.label||ep.name)}</strong><small>${fileRemoved?'Файл удалён':bytes(ep.size)}</small></div>${badge(label,color)}${ep.isPublished&&integrationsUI.connected()?`<button class="icon-btn" data-action="jellyfin" data-id="${e(p.hash)}" data-index="${e(ep.index)}" aria-label="Открыть ${e(ep.label)} в Jellyfin">${icon('play')}</button>`:''}${canDelete?`<button class="icon-btn" data-action="delete-episode" data-id="${e(p.hash)}" data-index="${e(ep.index)}" aria-label="Удалить ${e(ep.label)}">${icon('trash')}</button>`:''}</div>${ep.status==='DOWNLOADING'&&ep.progress>0&&ep.progress<1?`<div class="progress-wrap">${track(ep.progress)}</div>`:''}</div>`;}).join('')||'<p class="help">Информация о файлах пока недоступна.</p>'}<div class="action-error" role="alert"></div>`);}
function packActions(p){return shell('Действия с раздачей',`<p class="help">${e(p.title)}</p><div class="pack-tools-list">${p.kind!=='movie'?`<button data-action="confirm-finish" data-id="${e(p.hash)}" ${p.noNextSeason?'disabled':''}>${icon('check')}<span><strong>${p.noNextSeason?'Сериал завершён':'Завершить сериал'}</strong><small>Не предлагать следующий сезон</small></span></button>`:''}<button data-action="confirm-retry" data-id="${e(p.hash)}">${icon('refresh')}<span><strong>Проверить файлы</strong><small>Проверка целостности загрузки</small></span></button><button class="destructive" data-action="confirm-delete" data-id="${e(p.hash)}">${icon('trash')}<span><strong>Удалить раздачу</strong><small>Удалить её вместе с файлами</small></span></button></div><button class="secondary outline full" data-action="pack" data-id="${e(p.hash)}">${p.kind==='movie'?'Вернуться к фильму':'Вернуться к эпизодам'}</button>`);}
function showPack(id){const p=state.packs.find(x=>x.hash===id);if(p)openSheet('pack',id,packDetails(p));}
function updateOpenPack(){const p=state.packs.find(x=>x.hash===state.modal?.id);if(!p)return closeSheet();const scroll=sheet.scrollTop,action=document.activeElement?.dataset.action;sheet.innerHTML=packDetails(p);if(action)Array.from(sheet.querySelectorAll('[data-action]')).find(el=>el.dataset.action===action)?.focus({preventScroll:true});sheet.scrollTop=scroll;}
function confirm(title,description,action,id,index){openSheet('confirm',id,shell(title,`<p class="help">${e(description)}</p><div class="form-error" role="alert"></div><div class="dialog-footer"><button class="secondary outline" data-action="close">Отмена</button><button class="${action==='delete-pack'||action==='delete-ep'||action==='remove-sub'?'danger':'primary'}" data-action="${action}" data-id="${e(id)}" ${index!=null?`data-index="${e(index)}"`:''}>${action.startsWith('delete')||action==='remove-sub'?'Удалить':'Подтвердить'}</button></div>`));}
function addForm(result){const isSearch=!!result;openSheet(isSearch?'add-result':'add',isSearch?state.search.raw.indexOf(result):null,shell('Добавить в очередь',`<form id="add-form">${isSearch?`<p class="help">${e(result.title)}</p><p class="sheet-meta"><span>${bytes(result.size)}</span><span>${e(result.quality)}</span></p><input type="hidden" name="magnet" value="${e(result.magnet)}">${field('title','Название',queueTitle(result.title,state.search.query),'text','required maxlength="100"')}`:`<label class="field"><span>Magnet-ссылка</span><textarea name="magnet" required placeholder="magnet:?xt=urn:btih:…" autocapitalize="none" spellcheck="false"></textarea></label>${field('title','Название (необязательно)')}`}<label class="field"><span>Тип</span><select name="kind"><option value="series">Сериал</option><option value="movie" ${(result?.detectedKind||'').toLowerCase()==='movie'?'selected':''}>Фильм</option></select></label><div class="two-col series-fields">${field('season','Сезон',(isSearch&&state.search.kind==='series'&&state.search.season)||result?.detectedSeason||1,'text','inputmode="numeric"')}${field('startEpisode','Начиная с серии',result?.detectedStartEpisode||1,'text','inputmode="numeric"')}</div><div class="form-error" role="alert"></div><div class="dialog-footer"><button type="button" class="secondary outline" data-action="close">Отмена</button><button type="submit" class="primary">${icon('plus')}Добавить</button></div></form>`));updateSeriesFields();}
function updateSeriesFields(){const form=$('#add-form');if(form)form.querySelector('.series-fields').hidden=form.elements.kind.value==='movie';}
async function mutate(path,{method='POST',body,apply,message='Готово',keepSheet=false}={}){if(state.pending)return;state.pending=true;sheet.classList.add('pending');try{if(state.settings.demo){await apply?.();await refresh();}else{await request(path,{method,body});await refresh();}if(!keepSheet)closeSheet();toast(message);}catch(err){const target=sheet.querySelector('.form-error,.action-error');if(target)target.textContent=err.message;else toast(err.message);}finally{state.pending=false;sheet.classList.remove('pending');}}
function rememberSettingsForm(){const form=$('#settings-form');if(!form)return;settingsDraft.server=form.elements.server.value;settingsDraft.token=form.elements.token.value;}

let installPrompt=null;
const isStandalone=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
window.addEventListener('appinstalled',()=>{installPrompt=null;document.querySelector('[data-action="install"]')?.remove();});
async function installApp(){
 if(installPrompt){const prompt=installPrompt;installPrompt=null;await prompt.prompt();return;}
 const apple=/iPhone|iPad|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
 openSheet('install',null,shell('На экран Домой',apple?'<p class="help">В Safari откройте меню «Поделиться», затем выберите «На экран Домой» и нажмите «Добавить».</p><p class="help">Если есть переключатель «Открывать как веб-приложение», оставьте его включённым.</p>':'<p class="help">Откройте меню браузера и выберите «Установить приложение» или «Добавить на главный экран», если этот пункт доступен.</p>'));
}
const actions={
'want-result':el=>{const r=state.search.raw[+el.dataset.id];if(r)wishlist.add({title:queueTitle(r.title,state.search.query),year:r.year||r.title.match(/[\[(]((?:19|20)\d{2})(?=[\s,\])–-])/)?.[1],kind:mediaKind(r.detectedKind||state.search.kind)},el);},
install:installApp,
jellyfin:el=>integrationsUI.open(el.dataset.id,el.dataset.index===undefined?undefined:Number(el.dataset.index)),
'search-mode':el=>{searchMode=el.dataset.value;location.hash=searchMode==='discover'?'watch':searchMode==='random'?'random':'search';render();},'queue-filter':el=>{state.queueFilter=el.dataset.value;render();},'sub-filter':el=>{state.subFilter=el.dataset.value;render();},kind:el=>{state.search.kind=el.dataset.value;render();runSearch();},'retry-search':()=>runSearch(),refresh:()=>refresh(true),connect:()=>{location.hash='settings';},demo:()=>{generation++;state.settings.demo=true;state.error='';refresh();},close:closeSheet,pack:el=>showPack(el.dataset.id),'pack-menu':el=>{const p=state.packs.find(x=>x.hash===el.dataset.id);if(p)openSheet('pack-menu',p.hash,packActions(p));},add:()=>addForm(),'add-result':el=>addForm(state.search.raw[+el.dataset.id]),'detail-refresh':()=>refresh(true),
pause:()=>mutate('/api/queue/toggle-pause',{apply:()=>{demo.status.isPaused=!demo.status.isPaused;},message:state.status?.isPaused?'Очередь продолжена':'Очередь приостановлена',keepSheet:true}),
'search-example':el=>{state.search.query=el.dataset.query;render();runSearch();},
'clear-search':()=>{clearTimeout(searchTimer);searchAbort?.abort();state.search.query='';state.search.raw=[];state.search.loading=false;render();$('#search-input')?.focus();},
'confirm-delete':el=>confirm('Удалить раздачу?','Раздача и связанные файлы будут удалены на сервере.','delete-pack',el.dataset.id),
'confirm-retry':el=>confirm('Перепроверить файлы?','Сервер заново проверит целостность файлов этой раздачи.','retry-pack',el.dataset.id),
'confirm-finish':el=>confirm('Завершить раздачу?','Подтвердите завершение этой раздачи на сервере.','finish-pack',el.dataset.id),
'delete-pack':el=>mutate(`/api/packs/${encodeURIComponent(el.dataset.id)}`,{method:'DELETE',apply:()=>{demo.packs=demo.packs.filter(p=>p.hash!==el.dataset.id);},message:'Раздача удалена'}),
'retry-pack':el=>mutate(`/api/packs/${encodeURIComponent(el.dataset.id)}/retry`,{apply:()=>{const p=demo.packs.find(p=>p.hash===el.dataset.id);if(p)p.state='CHECKING';},message:'Проверка запущена'}),
'finish-pack':el=>mutate(`/api/packs/${encodeURIComponent(el.dataset.id)}/finish`,{apply:()=>{const p=demo.packs.find(p=>p.hash===el.dataset.id);if(p)p.noNextSeason=true;},message:'Раздача завершена'}),
'delete-episode':el=>confirm('Удалить файл серии?','Файл будет удалён на сервере. Это действие нельзя отменить.','delete-ep',el.dataset.id,el.dataset.index),
'delete-ep':el=>mutate(`/api/packs/${encodeURIComponent(el.dataset.id)}/episodes/${encodeURIComponent(el.dataset.index)}`,{method:'DELETE',apply:()=>{const ep=demo.packs.find(p=>p.hash===el.dataset.id)?.episodes.find(x=>x.index===+el.dataset.index);if(ep){ep.status='REMOVED';ep.isPublished=false;ep.progress=0;}},message:'Файл серии удалён'}),
'change-start':el=>{const p=state.packs.find(p=>p.hash===el.dataset.id);openSheet('start',p.hash,shell('С какой серии скачивать',`<form id="start-form"><p class="help">Загрузка продолжится с выбранной серии. Более ранние серии будут пропущены, а их загруженные файлы — удалены.</p><div class="two-col">${field('season','Сезон',p.season||1,'text','inputmode="numeric"')}${field('episode','Серия',p.startEpisode||1,'text','inputmode="numeric"')}</div><div class="form-error" role="alert"></div><div class="dialog-footer"><button type="button" class="secondary outline" data-action="close">Отмена</button><button class="primary">Применить</button></div></form>`));},
'add-sub':()=>openSheet('subscription',null,shell('Следить за сериалом',`<form id="subscription-form">${field('title','Название сериала','','text','required autocomplete="off" placeholder="Например, Разделение"')}<div id="show-suggestions" class="suggestions"></div><label class="field"><span>Качество</span><select name="quality"><option>Любое</option><option>1080p</option><option>4K</option><option>720p</option></select></label><label class="field"><span>Озвучка</span><select name="voice"><option>Любая</option><option>LostFilm</option><option>HDRezka</option><option>Дубляж</option><option>Кубик в Кубе</option><option>NewStudio</option></select></label><p class="help">Сервер предложит релиз при совпадении выбранных параметров.</p><div class="form-error" role="alert"></div><div class="dialog-footer"><button type="button" class="secondary outline" data-action="close">Отмена</button><button class="primary">Подписаться</button></div></form>`)),
'sub-menu':el=>{const s=state.subs.find(s=>s.id===el.dataset.id);confirm('Удалить подписку?',`Перестать отслеживать «${s.showTitle}»?`,'remove-sub',s.id);},
'remove-sub':el=>mutate(`/api/subscriptions/${encodeURIComponent(el.dataset.id)}`,{method:'DELETE',apply:()=>{demo.subs=demo.subs.filter(s=>s.id!==el.dataset.id);},message:'Подписка удалена'}),
import:el=>mutate(`/api/subscriptions/${encodeURIComponent(el.dataset.id)}/import`,{apply:()=>{const s=demo.subs.find(s=>s.id===el.dataset.id);s.status='UP_TO_DATE';},message:'Релиз добавлен в очередь',keepSheet:true}),
'pick-show':el=>{const form=$('#subscription-form');form.elements.title.value=el.dataset.title;form.dataset.tvmazeId=el.dataset.id;$('#show-suggestions').innerHTML='';},
number:el=>{rememberSettingsForm();const key=el.dataset.key,f=numericFields[key];openSheet('number',key,shell(f.title,`<form id="number-form"><p class="help">${e(f.help||'Введите точное значение')}. От ${f.min} до ${f.max} ${f.unit}.</p><div class="numeric-editor"><button class="icon-btn" type="button" data-action="step" data-delta="-1" aria-label="Уменьшить">${icon('minus')}</button><label class="numeric-value"><input aria-label="${f.title}" name="value" inputmode="${f.integer?'numeric':'decimal'}" value="${settingsDraft[key]??(key==='capGb'?0:50)}" autocomplete="off"><span>${f.unit}</span></label><button class="icon-btn" type="button" data-action="step" data-delta="1" aria-label="Увеличить">${icon('plus')}</button></div><div class="presets numeric-presets">${f.presets.map(n=>`<button type="button" class="chip ${Number(settingsDraft[key])===n?'active':''}" data-action="preset" data-value="${n}" aria-label="${n} ${f.unit}">${n}</button>`).join('')}</div><div class="form-error" role="alert"></div><div class="dialog-footer"><button type="button" class="secondary outline" data-action="close">Отмена</button><button class="primary">Применить</button></div></form>`));},
step:el=>{const f=numericFields[state.modal.id],input=$('#number-form').elements.value;const n=Number(input.value.replace(',','.'));input.value=Math.max(f.min,Math.min(f.max,(Number.isFinite(n)?n:f.min)+Number(el.dataset.delta)));},
preset:el=>{$('#number-form').elements.value.value=el.dataset.value;document.querySelectorAll('.numeric-presets .chip').forEach(b=>b.classList.toggle('active',b===el));},'toggle-token':el=>{const input=$('#settings-form').elements.token;input.type=input.type==='password'?'text':'password';el.setAttribute('aria-label',input.type==='password'?'Показать токен':'Скрыть токен');},
test:async el=>{const form=$('#settings-form');const result=$('#connection-result');el.disabled=true;result.textContent='Проверяем соединение…';try{const server=normalizeServer(form.elements.server.value);if(!server&&!state.gateway)throw new Error('Укажите адрес сервера или запустите локальный шлюз.');await request('/api/status',{server,token:form.elements.token.value});result.textContent='Сервер доступен';result.style.color='var(--green)';}catch(err){result.textContent=err.message;result.style.color='var(--red)';}finally{el.disabled=false;}}
};
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled||state.pending)return;actions[el.dataset.action]?.(el);});
document.addEventListener('keydown',event=>{if(event.target.matches('.media-card[role=button]')&&['Enter',' '].includes(event.key)){event.preventDefault();event.target.click();}});
sheet.addEventListener('click',event=>{if(event.target===sheet){const r=sheet.getBoundingClientRect();if(event.clientY<r.top||event.clientY>r.bottom||event.clientX<r.left||event.clientX>r.right)closeSheet();}});sheet.addEventListener('cancel',event=>{if(state.pending)event.preventDefault();});sheet.addEventListener('close',()=>{state.modal=null;document.body.classList.remove('modal-open');});
document.addEventListener('input',event=>{if(event.target.id==='search-input'){state.search.query=event.target.value;const clear=$('[data-action=clear-search]');if(clear)clear.hidden=!state.search.query;clearTimeout(searchTimer);searchTimer=setTimeout(runSearch,800);}if(event.target.name==='title'&&event.target.form?.id==='subscription-form'){const form=event.target.form;delete form.dataset.tvmazeId;clearTimeout(searchTimer);const query=event.target.value;searchTimer=setTimeout(async()=>{if(query.length<2||state.settings.demo)return;try{const suggestions=await request(`/api/shows/search?${new URLSearchParams({query})}`);if(!form.isConnected||form.elements.title.value!==query)return;$('#show-suggestions').innerHTML=(Array.isArray(suggestions)?suggestions:[]).slice(0,4).map(s=>`<button type="button" data-action="pick-show" data-id="${e(s.id)}" data-title="${e(s.name)}">${e(s.name)} <span class="muted">${e(s.premiered||'')}</span></button>`).join('');}catch{}},350);}});
document.addEventListener('change',async event=>{if(event.target.name==='uiTheme'){selectedTheme=applyTheme(event.target.value);toast('Тема сохранена на этом устройстве');return;}if(event.target.dataset.filter){state.search[event.target.dataset.filter]=event.target.value;renderResults();}if(event.target.name==='kind')updateSeriesFields();if(event.target.name==='demo'){rememberSettingsForm();settingsDraft.demo=event.target.checked;}});
document.addEventListener('submit',async event=>{const form=event.target;if(['tmdb-form','telegram-form','jellyfin-form'].includes(form.id))return;event.preventDefault();if(state.pending)return;try{const data=new FormData(form);if(form.id==='settings-form'){const server=normalizeServer(data.get('server'));const demoMode=data.get('demo')==='on';const token=String(data.get('token')||'').trim();if(!demoMode&&!server&&!state.gateway)throw new Error('Укажите адрес сервера или включите демо-режим.');const issue=connectionProblem(server,location.protocol);if(!demoMode&&issue)throw new Error(issue);
const connectionChanged=server!==state.settings.server||token!==state.token||state.settings.demo!==demoMode;
const patch=connectionChanged?{}:limitPatch(settingsDraft,dirtyLimits);
// Confirm durable server writes before claiming success or replacing local preferences.
state.pending=true;form.querySelector('[type=submit]').disabled=true;try{if(!demoMode){await request('/api/status',{server,token});if(Object.keys(patch).length)await request('/api/limits',{method:'POST',body:patch,server,token});if(state.gateway&&pollDirty){await request('/api/web-settings',{method:'POST',body:{pollSeconds:settingsDraft.pollSeconds},server:'',token});}}}finally{state.pending=false;form.querySelector('[type=submit]').disabled=false;}
state.settings={...settingsDraft,server,demo:demoMode};delete state.settings.token;state.token=token;localStorage.setItem('wn-settings',JSON.stringify(localSettings(state.settings)));sessionStorage.setItem('wn-token',token);dirtyLimits.clear();pollDirty=false;limitsLoaded=false;generation++;refreshPromise=null;state.packs=[];state.subs=[];state.status=null;state.connected=false;state.error='';await refresh();settingsDraft={...state.settings,token:state.token};schedulePoll();render();toast(connectionChanged?'Подключение сохранено. Лимиты загружены с сервера.':'Настройки сохранены');}

else if(form.id==='number-form'){const key=state.modal.id,f=numericFields[key];settingsDraft[key]=numeric(data.get('value'),f.min,f.max,!!f.integer);if(key!=='pollSeconds')dirtyLimits.add(key);else pollDirty=true;closeSheet();if(key==='pollSeconds')document.querySelector('[data-setting-value="pollSeconds"]').textContent=settingsDraft.pollSeconds+' сек';else $('#queue-limits').innerHTML=limitsContent();}
else if(form.id==='add-form'){const kind=data.get('kind'),result=state.modal.type==='add-result'?state.search.raw[+state.modal.id]:null;const body={title:String(data.get('title')||'').trim(),kind,season:kind==='series'?numeric(data.get('season'),1,999,true):1,startEpisode:kind==='series'?numeric(data.get('startEpisode'),1,9999,true):1,autoSeason:false};if([...body.title].length>100||body.title&&!body.title.replace(/[ .]/g,''))throw new Error('Введите название до 100 символов.');let magnet=String(data.get('magnet')||'').trim();if(result){state.pending=true;form.querySelector('.form-error').textContent='Получаем ссылку на раздачу…';const submit=form.querySelector('[type="submit"]');submit.disabled=true;try{magnet=await searchResultMagnet(result,link=>request('/api/search/resolve',{method:'POST',body:{link}}));result.magnet=magnet;}finally{state.pending=false;submit.disabled=false;form.querySelector('.form-error').textContent='';}}else if(!validMagnet(magnet))throw new Error('Вставьте корректную magnet-ссылку с хешем раздачи');body.magnet=magnet;await mutate('/api/packs/add',{body,apply:()=>{demo.packs.unshift({hash:`demo-${Date.now()}`,title:body.title||'Новая раздача',kind,season:body.season,startEpisode:body.startEpisode,state:'METADATA',progress:0,totalSize:0,episodes:[]});},message:'Раздача добавлена'});if(!sheet.open)location.hash='queue';}
else if(form.id==='start-form'){const id=state.modal.id;const body={season:numeric(data.get('season'),1,999,true),startEpisode:numeric(data.get('episode'),1,9999,true)};await mutate(`/api/packs/${encodeURIComponent(id)}/from`,{body,apply:()=>{Object.assign(demo.packs.find(p=>p.hash===id),body);},message:'Начало загрузки изменено'});}
else if(form.id==='subscription-form'){const title=String(data.get('title')||'').trim();if(!title)throw new Error('Введите название сериала');const body={title,preferredQuality:data.get('quality'),preferredVoice:data.get('voice'),tvmazeId:form.dataset.tvmazeId?Number(form.dataset.tvmazeId):null};await mutate('/api/subscriptions',{body,apply:()=>demo.subs.unshift({id:`sub-${Date.now()}`,showTitle:title,preferredQuality:body.preferredQuality,preferredVoice:body.preferredVoice,status:'ACTIVE'}),message:'Подписка добавлена'});}}
catch(err){const target=form.querySelector('.form-error');if(target)target.textContent=err.message;else toast(err.message);}});
window.addEventListener('hashchange',()=>{const route=routeForHash(location.hash);state.tab=route.tab;searchMode=route.mode;if(state.tab==='settings'){dirtyLimits.clear();pollDirty=false;settingsDraft={...state.settings,token:state.token};if(state.gateway)loadWebSettings().catch(err=>toast(err.message));}if(sheet.open)closeSheet();render();window.scrollTo(0,0);});
let metadataCache=read('wn-artwork-v3',{}),artworkJobs=new Map(),artworkActive=0;const artworkQueue=[];
async function json(url){const c=new AbortController();const t=setTimeout(()=>c.abort(),7000);try{const r=await fetch(url,{signal:c.signal,credentials:'omit'});return r.ok?await r.json():null;}catch{return null;}finally{clearTimeout(t);}}
async function findArtwork(title,rawKind,pack){const kind=mediaKind(rawKind),clean=queryTitle(title),key=`${kind}:${pack||clean}`;if(clean.length<2)return [];const old=metadataCache[key];const age=Date.now()-(old?.time||0);if(old&&age>=0&&age<(old.urls?.length?7*864e5:120000))return old.urls||[];
let urls=[];if(pack&&state.gateway&&!state.settings.demo){try{const match=await request('/api/artwork/pack/'+encodeURIComponent(pack),{server:''});if(/^\/api\/discover\/poster\/tt\d{5,12}$/.test(match.poster||''))urls=[match.poster];}catch{}}try{if(!urls.length)urls=await lookupArtwork(title,kind,json);}catch{}if(!urls.length&&old?.urls?.length)urls=old.urls;
metadataCache[key]={urls,time:Date.now()};metadataCache=Object.fromEntries(Object.entries(metadataCache).sort((a,b)=>b[1].time-a[1].time).slice(0,100));try{localStorage.setItem('wn-artwork-v3',JSON.stringify(metadataCache));}catch{}return urls;}
function artwork(title,kind,pack){const key=`${mediaKind(kind)}:${pack||title}`;if(!artworkJobs.has(key)){artworkJobs.set(key,new Promise(resolve=>{artworkQueue.push(async()=>{try{resolve(await findArtwork(title,kind,pack));}catch{resolve([]);}finally{artworkJobs.delete(key);artworkActive--;drainArtwork();}});drainArtwork();}));}return artworkJobs.get(key);}
function drainArtwork(){while(artworkActive<2&&artworkQueue.length){artworkActive++;artworkQueue.shift()();}}
const coverObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;coverObserver.unobserve(entry.target);loadCover(entry.target);}}, {rootMargin:'150px'});
function hydrateCovers(){document.querySelectorAll('.cover:not([data-observed])').forEach(el=>{el.dataset.observed='1';const image=el.querySelector('img');if(image)image.addEventListener('error',()=>{image.remove();loadCover(el);},{once:true});else coverObserver.observe(el);});}
async function loadCover(el){if(el.dataset.loading==='1')return;el.dataset.loading='1';const urls=await artwork(el.dataset.title,el.dataset.kind,el.dataset.pack);if(!el.isConnected||el.querySelector('img'))return;let index=0;function next(){if(!el.isConnected||index>=urls.length)return;const image=new Image();image.alt='';image.referrerPolicy='no-referrer';image.onerror=()=>{image.remove();next();};image.src=urls[index++];el.append(image);}next();}
function schedulePoll(){clearTimeout(pollTimer);pollTimer=setTimeout(async()=>{if(!document.hidden&&state.tab!=='settings'&&!state.pending){await refresh();if(state.gateway)await loadWebSettings().catch(()=>{});}schedulePoll();},Math.max(1,state.settings.pollSeconds)*1000);}
let incomingMagnet=null;
window.addEventListener('watchnext-magnet',event=>{if(typeof event.detail!=='string'||!validMagnet(event.detail))return;incomingMagnet=event.detail;if(state.connected){addForm();$('#add-form').elements.magnet.value=incomingMagnet;incomingMagnet=null;}});
async function initialize(){render();try{const response=await fetch('./web-config',{cache:'no-store'});if(response.ok){const config=await response.json();state.gateway=!!config.gateway;state.tmdb=!!config.tmdb;}}catch{}if(state.gateway)await loadWebSettings().catch(()=>{});render();await refresh();schedulePoll();if(incomingMagnet&&state.connected){addForm();$('#add-form').elements.magnet.value=incomingMagnet;incomingMagnet=null;}if('serviceWorker' in navigator&&window.isSecureContext)navigator.serviceWorker.register('./sw.js').catch(()=>{});}
initialize();
